import type { ComponentType, ReactNode } from "react";

import {
  Checkbox as BaseCheckbox,
  cn,
  Label,
} from "@lumeweb/portal-framework-ui-core";
import React from "react";

import { registerFormComponent } from ".";
import { FormFieldType } from "@/components"; // Use barrel export

interface CheckboxProps {
  autocomplete?: string;
  disabled?: boolean;
  label?: ComponentType<any> | ReactNode | string;
  name: string;
  onBlur?: () => void;
  onChange?: (checked: boolean) => void;
  value?: boolean;
}

export const Checkbox = React.forwardRef<HTMLButtonElement, CheckboxProps>(
  ({ autocomplete, label, ...props }, ref) => {
    return (
      <>
        <BaseCheckbox
          autoComplete={autocomplete}
          checked={props.value}
          disabled={props.disabled}
          id={props.name}
          name={props.name}
          onBlur={props.onBlur}
          onCheckedChange={props.onChange}
          ref={ref}
        />
        {label && (
          <Label
            className={cn("text-foreground", props.labelClassName)}
            htmlFor={props.name}>
            {typeof label === "function" ? React.createElement(label) : label}
          </Label>
        )}
      </>
    );
  },
);
Checkbox.displayName = "Checkbox";

export function registerCheckbox() {
  registerFormComponent(FormFieldType.CHECKBOX, Checkbox, {
    handlesLabel: true,
  });
}
